// The payoff: one row per approved story. Code because this aggregates three
// sources (story primaries, judge verdicts, run counts) into a single package shape.
const storyPrimaries = $('Cluster Similar Stories').all().map(item => item.json);
const judgedPrimaries = storyPrimaries.filter(story => story.rulesBand !== 'hardWin');

let judgeOutputs = [];
try {
  judgeOutputs = $('Relevance Judgment').all().map(item => item.json);
} catch (noJudgeRun) {
  judgeOutputs = []; // every story was a hard win; the LLM was never called
}

const verdictByCluster = {};
for (const story of storyPrimaries) {
  if (story.rulesBand === 'hardWin') {
    verdictByCluster[story.clusterId] = { verdict: 'approved', reason: 'Rules hard win - skipped the LLM entirely' };
  }
}
judgedPrimaries.forEach((story, judgeIndex) => {
  const judgeResult = judgeOutputs[judgeIndex] ? (judgeOutputs[judgeIndex].output || judgeOutputs[judgeIndex]) : null;
  verdictByCluster[story.clusterId] = {
    verdict: judgeResult && judgeResult.verdict ? judgeResult.verdict : 'rejected',
    reason: judgeResult && judgeResult.reason ? judgeResult.reason : 'No judge output received',
  };
});

const articlesIn = $('Read Articles from Sheets').all().length;
const survivedRules = $('Filter Rejected Articles').all().length;

const runId = $execution.id || 'manual';
const runAt = new Date().toISOString();
const runSignature = `${articlesIn}-${survivedRules}-${storyPrimaries.length}-${judgedPrimaries.length}`;

const packageRows = [];
for (const story of storyPrimaries) {
  const clusterVerdict = verdictByCluster[story.clusterId] || { verdict: 'rejected', reason: 'Missing verdict' };
  if (clusterVerdict.verdict !== 'approved') continue;
  const corroborating = (story.corroborating || [])
    .map(member => `${member.title} - ${member.source} (${member.url})`)
    .join(' | ');
  packageRows.push({ json: {
    run_id: runId,
    run_at: runAt,
    run_signature: runSignature,
    cluster_id: story.clusterId,
    best_title: story.title,
    best_source: story.source,
    best_url: story.url,
    rules_score: story.rulesScore,
    verdict_reason: clusterVerdict.reason,
    corroborating_sources: corroborating || 'none - single-source story',
    articles_in_cluster: story.clusterSize,
    run_articles_in: articlesIn,
    run_survived_rules: survivedRules,
    run_unique_stories: storyPrimaries.length,
    run_llm_calls: judgedPrimaries.length,
  }});
}
return packageRows;

// Writes every article's fate back to the seen ledger, matched by URL.
// Recomputes the same verdict mapping the assembler uses - both nodes read
// identical sources, so they cannot drift.
const scoredArticles = $('Apply Scoring Rules').all().map(item => item.json);
const storyPrimaries = $('Cluster Similar Stories').all().map(item => item.json);
const judgedPrimaries = storyPrimaries.filter(story => story.rulesBand !== 'hardWin');
let judgeOutputs = [];
try {
  judgeOutputs = $('Relevance Judgment').all().map(item => item.json);
} catch (noJudgeRun) {
  judgeOutputs = [];
}

const config = $('Set Workflow Context').first().json;
const runId = String($execution.id || 'manual');

const verdictByCluster = {};
for (const story of storyPrimaries) {
  if (story.rulesBand === 'hardWin') {
    verdictByCluster[story.clusterId] = { verdict: 'approved', reason: 'Rules hard win - skipped the LLM entirely' };
  }
}
judgedPrimaries.forEach((story, judgeIndex) => {
  const judgeResult = judgeOutputs[judgeIndex] ? (judgeOutputs[judgeIndex].output || judgeOutputs[judgeIndex]) : null;
  verdictByCluster[story.clusterId] = {
    verdict: judgeResult && judgeResult.verdict ? judgeResult.verdict : 'rejected',
    reason: judgeResult && judgeResult.reason ? judgeResult.reason : 'No judge output received',
  };
});

const outcomeByUrl = {};
for (const article of scoredArticles) {
  if (article.rulesBand === 'reject') {
    outcomeByUrl[article.url] = {
      status: 'rejected_rules',
      rules_score: article.rulesScore,
      reason: `Rules score ${article.rulesScore} below reject threshold ${config.rulesRejectThreshold}`,
      cluster_id: '',
    };
  }
}
for (const story of storyPrimaries) {
  const clusterVerdict = verdictByCluster[story.clusterId] || { verdict: 'rejected', reason: 'Missing verdict' };
  outcomeByUrl[story.url] = {
    status: clusterVerdict.verdict === 'approved' ? 'approved' : 'rejected_judge',
    rules_score: story.rulesScore,
    reason: clusterVerdict.reason,
    cluster_id: story.clusterId,
  };
  for (const member of story.corroborating || []) {
    const memberScored = scoredArticles.find(candidate => candidate.url === member.url);
    outcomeByUrl[member.url] = {
      status: 'corroborating',
      rules_score: memberScored ? memberScored.rulesScore : '',
      reason: `Duplicate coverage of: ${story.title}`,
      cluster_id: story.clusterId,
    };
  }
}

return Object.entries(outcomeByUrl).map(([url, outcome]) => ({ json: { url, ...outcome, run_id: runId } }));
